const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',chart:'<path d="M3 3v18h18M8 16v-4M13 16V8M18 16V5"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z"/><path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3 3-1 2 3h3l1-3 3-1 2-3-2-2 1-3-2-3-3 1-2-3z"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1zM9 21v-8h6v8"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8a2.5 2.5 0 1 1 4 2.5c-1 .5-1.5 1-1.5 2.5M12 17h.01"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',vote:'<path d="m7 4 4-2 7 10-4 3zM5 12H3v9h18v-9h-3M7 17h10"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>'};
const I=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Sarah Mitchell','James Wilson','David & Emma Turner','Michael Roberts','Priya Naidoo','John Anderson','Thandi Mokoena','Peter van der Merwe','Linda Jacobs','Ahmed Patel','Catherine Smith','Daniel Williams','Rebecca Thomas','Sipho Dlamini','Olivia Brown','Robert Taylor','Nandi Khumalo','William Davies','Grace Martin','Matthew Clark'];
const initialOwners=Array.from({length:148},(_,i)=>({id:i+1,name:i<20?names[i]:names[i%20].replace(/ & Emma/,'')+' '+String.fromCharCode(65+Math.floor(i/20)),unit:String(i+1).padStart(3,'0'),email:i===0?'sarah.mitchell@example.com':`owner${i+1}@example.com`,balance:i<136?0:750+(i-136)*250,approved:i<136,registered:i<112,invited:i<142,meetingInvited:i<112}));
const initialMotions=[{id:1,title:'Approval of the previous AGM minutes',description:'To approve the minutes of the Annual General Meeting held on 5 November 2025 as a true and accurate record of proceedings.',type:'Ordinary',threshold:50},{id:2,title:'Adoption of the annual financial statements',description:'To consider and adopt the audited annual financial statements for the financial year ended 30 June 2026.',type:'Ordinary',threshold:50},{id:3,title:'Approval of the 2027 operating budget',description:'To approve the proposed operating budget for the 2027 financial year, including a 6% annual levy increase, effective 1 January 2027.',type:'Ordinary',threshold:50},{id:4,title:'Approval of the reserve fund contribution',description:'To approve an additional reserve fund contribution of R1,200 per property, payable in two equal instalments, for the planned perimeter security upgrade.',type:'Special',threshold:75}];
let state={owners:initialOwners,motions:initialMotions,status:'live',meeting:'2026 Annual General Meeting',hoa:'Oakwood Estate HOA',date:'2026-11-04',time:'18:00',quorum:50,started:new Date(Date.now()-2520000).toISOString(),audit:[],ballots:[]};
for(let j=0;j<83;j++)state.ballots.push({ownerId:j+1,time:new Date(Date.now()-(83-j)*29000).toISOString(),choices:state.motions.map((m,k)=>({motionId:m.id,choice:(j+k*3)%20<15?'For':(j+k*3)%20<18?'Against':'Abstained'})),receipt:`QRM-2026-${String(j+1).padStart(4,'0')}`});
const seedEvents=[['MEETING_OPENED','Managing agent','Meeting opened. Voting invitations prepared for 112 registered, eligible owners.'],['INVITATIONS_PREPARED','Managing agent','Registration invitations prepared for eligible owners (demo).'],['ELIGIBILITY_VERIFIED','Managing agent','136 owners verified as paid up and eligible.'],['OWNERS_IMPORTED','Managing agent','148 owner records imported from accounting export.']];
state.audit=seedEvents.map((e,i)=>({id:4-i,time:new Date(Date.now()-(i+1)*1200000).toISOString(),action:e[0],actor:e[1],details:e[2]}));
let page='Overview',motionFilter='All motions',ownerFilter='all',ownerSearch='',ownerPage=1,auditSearch='',view='admin',voter={stage:'welcome',ownerId:1,index:0,choices:{},verified:false},pendingImport=[],modalName='',lastFocus=null;
const eligible=o=>o.balance<=0&&o.approved;
const stats=()=>({total:state.owners.length,eligible:state.owners.filter(eligible).length,registered:state.owners.filter(o=>o.registered&&eligible(o)).length,voted:state.ballots.length});
const tally=id=>{let r={For:0,Against:0,Abstained:0};state.ballots.forEach(b=>{const c=b.choices.find(x=>x.motionId===id);if(c)r[c.choice]++});return r};
const pct=(a,b)=>b?Math.round(a/b*100):0;
const badge=(text,kind)=>`<span class="badge ${kind||'neutral'}">${esc(text)}</span>`;
const btn=(text,action,icon='',kind='',extra='')=>`<button type="${extra.includes('type=')?'submit':'button'}" class="button ${kind}" data-action="${action}" ${extra}>${icon?I(icon):''}${text}</button>`;
function log(action,actor,details){state.audit.unshift({id:Math.max(0,...state.audit.map(e=>e.id))+1,time:new Date().toISOString(),action,actor,details})}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),4200)}
function dateTime(t){return new Date(t).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function initials(n){return n.split(' ').filter(x=>x!=='&').slice(0,2).map(x=>x[0]).join('')}
function ownerCell(o){return `<div class="owner-cell"><div class="avatar">${initials(o.name)}</div><div><strong>${esc(o.name)}</strong><small>${esc(o.email)}</small></div></div>`}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">Your community. Every voice.</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="row-actions">${actions}</div></div>`}
function render(){if(view==='voter'){renderVoter();return}const s=stats();document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brandmark"></span>quorum<span style="font-size:21px;color:#8ca36c">.</span></div><div class="workspace"><div class="square-icon">${I('home')}</div><div><strong>${esc(state.hoa)}</strong><small>Managing agent workspace</small></div></div><div class="section-label">Workspace</div><nav class="nav" aria-label="Main navigation">${[['Overview','grid'],['Meetings','calendar'],['Owners & voters','users'],['Results & reports','chart'],['Audit trail','file']].map(([p,i])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${I(i)}${p}${p==='Meetings'?'<span class="counter">1</span>':''}</button>`).join('')}<div style="height:13px"></div><button data-page="Settings" class="${page==='Settings'?'active':''}">${I('settings')}Settings</button></nav><div class="sidebar-bottom"><div class="help-box">${I('shield')}<h3 style="font-size:12px;margin-top:10px">A confident meeting starts here.</h3><p>Everything you need for a clear, well-run voting process.</p><button data-action="guide">View meeting guide ${I('arrow')}</button></div><div class="profile"><div class="avatar">JL</div><div><strong>Jessica Lawson</strong><small>Managing agent</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-toggle" data-action="menu" aria-label="Toggle navigation">${I('menu')}</button>${I('home')}<span>/</span><span>Workspace</span><span>/</span><b>${page}</b></div><div class="top-actions"><button class="demo-tag" data-action="demo-info">DEMO WORKSPACE</button><button class="iconbtn" data-action="guide" aria-label="Help">${I('help')}</button><button class="iconbtn" data-action="notifications" aria-label="View notifications">${I('bell')}<i class="notification-dot"></i></button><div class="avatar">JL</div></div></header><div class="content">${page==='Overview'?overview():page==='Meetings'?meetings():page==='Owners & voters'?owners():page==='Results & reports'?results():page==='Audit trail'?audit():settings()}<footer class="page-foot"><span>${I('lock')} Private meeting workspace · Demo data only</span><span>Quorum © 2026 <span style="padding:0 9px">·</span> Every voice. Accounted for.</span></footer></div></main></div>`}
function statCards(){let s=stats();return `<div class="stats">${[['Total owners',s.total,'','users',`${s.total} properties in your community`],['Eligible voters',s.eligible,'','shield',`${s.total-s.eligible} owners with outstanding levies`],['Registered voters',s.registered,`/ ${s.eligible}`,'users',`<b>${pct(s.registered,s.eligible)}%</b> of eligible owners registered`],['Votes submitted',s.voted,`/ ${s.eligible}`,'vote',`<b>${pct(s.voted,s.eligible)}%</b> voter participation`]].map(([label,value,den,icon,foot],i)=>`<div class="stat"><div class="stat-label">${label}${I(icon)}</div><div class="stat-value">${value}<small>${den}</small></div><div class="stat-foot">${i>1?'<i class="dot"></i>':''}${foot}</div>${i>1?`<div class="stat-progress"><i style="width:${pct(value,s.eligible)}%"></i></div>`:''}</div>`).join('')}</div>`}
function meetingBanner(){return `<section class="meeting-banner"><div>${badge(state.status==='live'?'Meeting in progress':state.status==='closed'?'Meeting closed':'Ready to start',state.status==='live'?'live':'neutral')}<h2>${esc(state.meeting)}</h2><div class="meeting-meta"><span>${I('calendar')}${new Date(state.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</span><span>${I('clock')}${esc(state.time)} UTC</span><span>${I('home')}${esc(state.hoa)}</span></div></div><div class="banner-right"><div class="banner-time"><p>${state.status==='closed'?'FINAL RECORD':'MEETING STATUS'}</p><strong>${state.status==='live'?'Voting is open':state.status==='closed'?'Voting closed':'Not yet started'}</strong></div>${btn(state.status==='closed'?'View results':'Manage meeting',state.status==='closed'?'go-results':'go-meetings','arrow')}</div></section>`}
function motionRow(m){let t=tally(m.id),total=t.For+t.Against+t.Abstained;return `<div class="motion-row"><div class="motion-number">${String(m.id).padStart(2,'0')}</div><div class="motion-content"><div class="motion-title"><h3>${esc(m.title)}</h3>${badge(state.status==='closed'?'Closed':'Voting open',state.status==='closed'?'neutral':'eligible')}</div><p>${esc(m.type)} resolution <span style="padding:0 5px">·</span> ${m.threshold}% ${m.threshold===50?'majority':'approval threshold'}</p><div class="vote-bars"><span style="width:${pct(t.For,total)}%"></span><span style="width:${pct(t.Against,total)}%"></span><span style="width:${pct(t.Abstained,total)}%"></span></div><div class="motion-bottom"><div class="motion-legend"><span><i></i>For ${t.For}</span><span><i></i>Against ${t.Against}</span><span><i></i>Abstained ${t.Abstained}</span></div><span>${total} votes</span></div></div></div>`}
function overview(){let s=stats(),q=pct(s.voted,s.eligible),shown=state.motions.filter(m=>motionFilter==='All motions'||m.type===motionFilter).slice(0,3);return heading('Meeting overview','A clear view of your community’s decisions, all in one place.',btn('Preview voter experience','voter-preview','eye')+btn('Invite voters','invite','mail','primary'))+meetingBanner()+statCards()+`<div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>Meeting motions</h2><p>Track votes as your community makes decisions.</p></div><button class="text-button" data-action="go-meetings">View all ${I('arrow')}</button></div><div class="tabs">${['All motions','Ordinary','Special'].map(x=>`<button data-motion-filter="${x}" class="${motionFilter===x?'active':''}">${x} <span class="count">${state.motions.filter(m=>x==='All motions'||m.type===x).length}</span></button>`).join('')}</div>${shown.map(motionRow).join('')}<div class="motion-footer">${I('shield')} Each submitted ballot is linked to a verified owner.</div></section><section class="panel owners-preview"><div class="panel-head"><div><h2>Owner register</h2><p>Verified owners. Confident decisions.</p></div><button class="text-button" data-action="go-owners">View all owners ${I('arrow')}</button></div><div class="table-scroll"><table><thead><tr><th>Owner</th><th>Unit</th><th>Eligibility</th><th>Voting status</th></tr></thead><tbody>${[state.owners[0],state.owners[3],state.owners[113],state.owners[136]].filter(Boolean).map(o=>`<tr><td>${ownerCell(o)}</td><td>${esc(o.unit)}</td><td>${badge(eligible(o)?'Eligible':'Not eligible',eligible(o)?'eligible':'ineligible')}</td><td>${badge(state.ballots.some(b=>b.ownerId===o.id)?'Voted':o.registered?'Registered':'Invited',state.ballots.some(b=>b.ownerId===o.id)?'complete':o.registered?'neutral':'invited')}</td></tr>`).join('')}</tbody></table></div></section></div><div class="right-column"><section class="panel"><div class="panel-head"><div><h2>Meeting quorum</h2><p>Every verified vote brings us together.</p></div>${I('users')}</div><div class="quorum-body"><div class="quorum-visual"><div class="donut" style="background:conic-gradient(#6d8b55 0deg ${Math.min(q,100)*3.6}deg,#eef1e6 ${Math.min(q,100)*3.6}deg)"><div class="donut-text"><strong>${q}%</strong><small>participation</small></div></div></div><div class="quorum-detail"><span>Owners who voted</span><b>${s.voted} of ${s.eligible}</b></div><div class="quorum-detail"><span>Required quorum</span><b>${state.quorum}%</b></div><div class="notice">${I(q>=state.quorum?'check':'clock')}${q>=state.quorum?'Quorum reached. Your meeting can proceed.':'Waiting for more eligible owners to participate.'}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>A record of what’s happening.</p></div>${I('clock')}</div><div class="activity-list">${[{action:'VOTE_SUBMITTED',details:`${s.voted} owners have submitted their ballots.`,time:state.ballots.at(-1)?.time||new Date().toISOString()},...state.audit].slice(0,4).map(e=>`<div class="activity-item"><div class="activity-icon">${I(e.action.includes('VOTE')?'vote':e.action.includes('INVIT')?'mail':e.action.includes('MEETING')?'calendar':'shield')}</div><div class="activity-copy"><p>${esc(e.details)}</p><small>${dateTime(e.time)} UTC</small></div></div>`).join('')}</div><div class="panel-bottom"><span>Every action, accounted for.</span><button class="text-button" data-action="go-audit">View audit trail ${I('arrow')}</button></div></section></div></div>`}
function meetings(){return heading('Meetings','Prepare the agenda, manage the meeting, and bring every vote together.',btn('Preview voter experience','voter-preview','eye')+btn('Edit meeting','edit-meeting','settings'))+meetingBanner()+`<div class="callout">${I('shield')}<div><strong>${state.status==='closed'?'This meeting is closed.':'You’re in control of the meeting.'}</strong> ${state.status==='closed'?'Ballots are locked. Download the final results and audit file for verification.':'Registered, eligible owners can vote while the meeting is open. Closing the meeting locks voting.'}</div></div><section class="panel"><div class="panel-head"><div><h2>Agenda & motions</h2><p>${state.motions.length} motions · One complete ballot per owner</p></div>${btn('Add motion','add-motion','plus','',state.ballots.length?'disabled title="Agenda is locked after the first ballot"':'')}</div>${state.motions.map(m=>motionRow(m)).join('')}</section><section class="panel"><div class="meeting-card"><div><h2>${state.status==='closed'?'Meeting complete':'Meeting controls'}</h2><p>${state.status==='closed'?'Results and the closing audit record are available for your review.':'Send a meeting invitation to registered, eligible owners, or close the voting period.'}</p></div><div class="row-actions">${state.status==='closed'?btn('Download audit file','download-audit','download','primary'):btn('Meeting invitations','meeting-invites','mail')+btn('Close meeting','close-meeting','lock','danger')}</div></div></section>`}
function filteredOwners(){return state.owners.filter(o=>(ownerFilter==='all'||ownerFilter==='eligible'&&eligible(o)||ownerFilter==='ineligible'&&!eligible(o)||ownerFilter==='registered'&&o.registered||ownerFilter==='not-voted'&&!state.ballots.some(b=>b.ownerId===o.id))&&`${o.name} ${o.email} ${o.unit}`.toLowerCase().includes(ownerSearch.toLowerCase()))}
function ownersTable(){let all=filteredOwners(),pages=Math.max(1,Math.ceil(all.length/10));ownerPage=Math.min(ownerPage,pages);return `<div class="table-scroll"><table><thead><tr><th>Owner</th><th>Unit</th><th>Levy balance</th><th>Eligibility</th><th>Registration</th><th>Ballot</th><th></th></tr></thead><tbody>${all.slice((ownerPage-1)*10,ownerPage*10).map(o=>`<tr><td>${ownerCell(o)}</td><td>${esc(o.unit)}</td><td>${o.balance<=0?'Paid up':'R '+Number(o.balance).toLocaleString('en-ZA',{minimumFractionDigits:2})}</td><td>${badge(eligible(o)?'Verified':o.balance>0?'Levy overdue':'Needs review',eligible(o)?'eligible':o.balance>0?'ineligible':'pending')}</td><td>${badge(o.registered?'Registered':o.invited?'Invited':'Not invited',o.registered?'registered':o.invited?'invited':'neutral')}</td><td>${badge(state.ballots.some(b=>b.ownerId===o.id)?'Submitted':'Not voted',state.ballots.some(b=>b.ownerId===o.id)?'complete':'neutral')}</td><td><button class="text-button" data-owner="${o.id}">Review ${I('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No owners match your search.</td></tr>'}</tbody></table></div><div class="panel-bottom"><span>${all.length?`${(ownerPage-1)*10+1}–${Math.min(ownerPage*10,all.length)} of ${all.length}`:'0'} owners</span><div class="row-actions">${btn('Previous','owners-prev','','small',ownerPage<=1?'disabled':'')}<span>Page ${ownerPage} of ${pages}</span>${btn('Next','owners-next','','small',ownerPage>=pages?'disabled':'')}</div></div>`}
function owners(){return heading('Owners & voters','Start with an accurate register. Give every eligible owner a voice.',btn('Import owners','import','upload')+btn('Invite voters','invite','mail','primary'))+statCards()+`<section class="panel"><div class="panel-head"><div><h2>Owner register</h2><p>Levy balances and eligibility from your accounting export.</p></div>${btn('Export register','export-owners','download','small')}</div><div class="toolbar"><label class="search">${I('search')}<span class="visually-hidden">Search owners</span><input id="owner-search" placeholder="Search owner, email or unit…" value="${esc(ownerSearch)}"></label><select id="owner-filter" aria-label="Filter owners">${[['all','All owners'],['eligible','Eligible owners'],['ineligible','Needs attention'],['registered','Registered'],['not-voted','Not yet voted']].map(([v,l])=>`<option value="${v}" ${ownerFilter===v?'selected':''}>${l}</option>`).join('')}</select></div><div id="owners-table">${ownersTable()}</div></section><p class="note-banner">${I('shield')} An owner must be paid up and verified by the managing agent to be eligible. Imports never alter submitted ballots.</p>`}
function results(){let s=stats();return heading('Results & reports','Transparent outcomes, with a record behind every decision.',btn('Export owner votes','export-votes','download')+btn('Download results','export-results','download','primary'))+`<div class="callout">${I('chart')}<div><strong>${state.status==='closed'?'Final meeting results':'Live results · provisional'}</strong> · ${s.voted} complete ballots from ${s.eligible} eligible owners. One owner, one vote. Abstentions are excluded from approval percentages.</div></div><div class="results-summary">${[['Participation',pct(s.voted,s.eligible)+'%',`${s.voted} of ${s.eligible} eligible owners voted`],['Quorum',pct(s.voted,s.eligible)>=state.quorum?'Reached':'Pending',`${state.quorum}% of eligible owners required`],['Motions',state.motions.length,`${state.motions.filter(m=>passes(m)).length} currently meet their approval threshold`]].map(([l,v,f])=>`<div class="panel stat" style="margin-bottom:0"><div class="stat-label">${l}${I('chart')}</div><div class="stat-value" style="font-size:27px">${v}</div><div class="stat-foot">${f}</div></div>`).join('')}</div><div class="settings-grid">${state.motions.map(m=>{let t=tally(m.id),total=t.For+t.Against+t.Abstained,approval=pct(t.For,t.For+t.Against);return `<section class="panel result-card"><div style="display:flex;justify-content:space-between">${badge('Motion '+String(m.id).padStart(2,'0'),'neutral')}${badge(passes(m)?(state.status==='closed'?'Approved':'On track to pass'):(state.status==='closed'?'Not approved':'Below threshold'),passes(m)?'eligible':'pending')}</div><h3>${esc(m.title)}</h3><div class="result-value">${approval}% <span style="font-size:12px;color:#8f9a87;font-family:DM Sans">approval</span></div><p>${m.type} resolution · ${m.threshold===50?'More than 50%':m.threshold+'% or more'} approval required</p><div class="vote-bars" style="height:8px"><span style="width:${pct(t.For,total)}%"></span><span style="width:${pct(t.Against,total)}%"></span><span style="width:${pct(t.Abstained,total)}%"></span></div><div class="result-meta"><div>For<b>${t.For}</b></div><div>Against<b>${t.Against}</b></div><div>Abstained<b>${t.Abstained}</b></div><div>Total<b>${total}</b></div></div></section>`}).join('')}</div><p class="note-banner">Approval and quorum rules shown are demo defaults. Confirm the HOA’s governing rules, vote weighting, and applicable requirements before a live meeting.</p>`}
function passes(m){let t=tally(m.id),n=t.For+t.Against;if(!n||pct(stats().voted,stats().eligible)<state.quorum)return false;return m.threshold===50?t.For/n>.5:t.For/n>=m.threshold/100}
function allAudit(){return [...state.audit,...state.ballots.map((b,i)=>({id:'B'+(i+1),time:b.time,action:'VOTE_SUBMITTED',actor:state.owners.find(o=>o.id===b.ownerId)?.name||'Owner '+b.ownerId,details:`Complete ballot registered. Receipt ${b.receipt}.`}))].sort((a,b)=>new Date(b.time)-new Date(a.time))}
function auditRows(){let rows=allAudit().filter(e=>`${e.action} ${e.actor} ${e.details}`.toLowerCase().includes(auditSearch.toLowerCase()));return `<div class="table-scroll"><table><thead><tr><th>Timestamp (UTC)</th><th>Action</th><th>Actor</th><th>Details</th></tr></thead><tbody>${rows.slice(0,100).map(e=>`<tr><td>${dateTime(e.time)}</td><td><span class="audit-type">${esc(e.action)}</span></td><td>${esc(e.actor)}</td><td style="white-space:normal;min-width:230px;line-height:1.7">${esc(e.details)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching events.</td></tr>'}</tbody></table></div><div class="panel-bottom"><span>${Math.min(100,rows.length)} of ${rows.length} events shown</span><span>Download for the complete record</span></div>`}
function audit(){return heading('Audit trail','A clear record from the first invitation to the final vote.',btn('Download audit CSV','export-audit-csv','download')+btn('Download audit file','download-audit','download','primary'))+`<div class="callout">${I('shield')}<div><strong>${state.status==='closed'?'Closing record ready for verification.':'Your meeting has an active audit record.'}</strong> ${state.status==='closed'?'The final JSON includes owner snapshots, ballots, outcomes, and events.':'Closing the meeting generates a final audit package for review.'}</div></div><section class="panel"><div class="toolbar"><label class="search" style="max-width:390px">${I('search')}<span class="visually-hidden">Search audit trail</span><input id="audit-search" placeholder="Search actions, owners or details…" value="${esc(auditSearch)}"></label><span style="color:#8e9a83;font-size:11px">${allAudit().length} recorded events</span></div><div id="audit-table">${auditRows()}</div></section><p class="note-banner">Demo records are held in this open browser tab. A production audit requires protected server storage and retention controls.</p>`}
function settings(){return heading('Workspace settings','The details and rules that keep your meeting running smoothly.')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Community & meeting</h2></div><form id="settings-form" class="panel-inner"><div class="field"><label for="hoa-name">Community name</label><input id="hoa-name" name="hoa" value="${esc(state.hoa)}" required maxlength="80"></div><div class="field"><label for="meeting-name">Meeting title</label><input id="meeting-name" name="meeting" value="${esc(state.meeting)}" required maxlength="100"></div><div class="grid2"><div class="field"><label for="meeting-date">Meeting date</label><input id="meeting-date" name="date" type="date" value="${state.date}" required></div><div class="field"><label for="meeting-time">Start time (UTC)</label><input id="meeting-time" name="time" type="time" value="${state.time}" required></div></div><div class="field"><label for="quorum-input">Quorum required (%)</label><input id="quorum-input" name="quorum" type="number" value="${state.quorum}" min="1" max="100" required ${state.ballots.length?'disabled':''}><small>One vote per eligible owner. Voting rules lock once the first ballot is submitted.</small></div>${btn('Save changes','submit-settings','check','primary','type="submit"')}</form></section><div><section class="panel"><div class="panel-head"><h2>Voting safeguards</h2></div><div class="panel-inner" style="padding-top:0">${[['Eligibility check','Paid-up levies and managing-agent verification'],['Complete ballots','A choice is required for every motion'],['Single submission','One complete ballot per owner'],['Meeting lock','Voting ends when the meeting closes']].map(([h,p])=>`<div class="setting-row"><div><p>${h}</p><small>${p}</small></div>${I('shield')}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Connections</h2></div><div class="panel-inner" style="padding-top:0"><div class="setting-row"><div><p>Email delivery</p><small>Invitations and OTP emails</small></div>${badge('Demo mode','pending')}</div><div class="setting-row"><div><p>Accounting system</p><small>Excel / CSV import available</small></div>${badge('File import','neutral')}</div><div class="notice">${I('help')}Live email, secure owner authentication, and a shared database require production setup.</div></div></section></div></div>`}
function modal(title,body,footer='',wide=false){lastFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" data-action="close-modal" aria-label="Close dialog">${I('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>document.querySelector('.modal input:not([type=file]), .modal button')?.focus(),20)}
function closeModal(){document.getElementById('modal-root').innerHTML='';modalName='';lastFocus?.focus()}
function openInvite(meeting=false){modalName=meeting?'meeting-invites':'invite';let candidates=state.owners.filter(o=>eligible(o)&&(!meeting||o.registered));modal(meeting?'Invite owners to vote':'Invite owners to register',`<p>${meeting?'Prepare meeting access emails for registered, eligible owners. Eligibility is checked again before a ballot can be submitted.':'Invite eligible owners to create their username and password. Only paid-up, verified owners are included.'}</p><div class="import-summary"><strong>${candidates.length} eligible ${meeting?'registered voters':'owners'}</strong><br>${state.owners.length-candidates.length} owners excluded from this invitation.</div><div class="email-preview"><strong>${meeting?'Voting is now open':'You’re invited to register'} · ${esc(state.hoa)}</strong>Hello {{owner_name}},<br><br>${meeting?`Voting for ${esc(state.meeting)} is now open. Sign in with your username and password, then verify the one-time code to cast your ballot.`:`Please register for ${esc(state.meeting)}. Select your personal invitation link to create your username and password.`}<br><br><span style="display:inline-block;background:#174c3e;color:white;padding:7px 15px;border-radius:5px">${meeting?'Open voting app':'Register to vote'} →</span></div><div class="notice">${I('mail')}Demo mode: emails are previewed here and are not delivered. No live email service is configured.</div>`,btn('Cancel','close-modal')+btn('Prepare '+candidates.length+' invitations',meeting?'confirm-meeting-invites':'confirm-invites','mail','primary'))}
function openImport(){pendingImport=[];modalName='import';modal('Import owner register',`<p>Upload the Excel or CSV export from your accounting system. Review the records before adding them to your register.</p><div class="notice" style="margin-bottom:15px;margin-top:0">${I('help')}Required columns: owner_name, email, unit, levy_balance. Positive balances are overdue. Paid-up owners still need MA verification.</div><button class="text-button" data-action="template">Download import template ${I('download')}</button><label class="upload-area" style="display:block">${I('upload')}<strong>Choose an accounting export</strong><p>.xlsx, .xls or .csv · Up to 2 MB</p><input type="file" id="owner-file" accept=".xlsx,.xls,.csv" aria-label="Choose owner file"></label><div id="import-preview"></div><p class="form-note">Existing units are matched to the register. Existing ballots are preserved; ownership or email changes for an owner who has voted are rejected.</p>`,btn('Cancel','close-modal')+btn('Import records','confirm-import','upload','primary','id="import-confirm" disabled'))}
function openOwner(id){let o=state.owners.find(x=>x.id===id);modal('Review owner',`<div style="margin-bottom:24px">${ownerCell(o)}</div><form id="owner-review-form" data-id="${o.id}"><div class="grid2"><div class="field"><label>Unit</label><input value="${esc(o.unit)}" disabled></div><div class="field"><label>Levy balance (R)</label><input name="balance" type="number" step="0.01" value="${o.balance}" required ${state.status==='closed'?'disabled':''}></div></div><label class="checkbox-row"><input name="approved" type="checkbox" ${o.approved?'checked':''} ${state.status==='closed'?'disabled':''}><span>I have checked the accounting record and verified this owner’s voting entitlement.</span></label><div class="notice">${I('shield')}Eligibility requires a zero or credit levy balance and managing-agent verification. Existing submitted ballots stay in the audit record.</div><div style="margin-top:22px;display:flex;justify-content:flex-end;gap:10px">${btn('Cancel','close-modal')}${btn('Save verification','save-owner','check','primary','type="submit" '+(state.status==='closed'?'disabled':''))}</div></form>`)}
function guide(){modal('Your meeting, step by step',`<p>A simple path from your owner register to a verified meeting record.</p>${[['Import & verify','Upload an accounting export. Review levy balances and verify who is entitled to vote.'],['Invite & register','Prepare personal registration invitations. Owners create a username and password.'],['Open & vote','Invite registered owners when the meeting opens. They sign in, verify an OTP, and vote on each motion.'],['Close & verify','Close voting, review the outcomes, and download the full audit file for final verification.']].map(([h,p],i)=>`<div class="guide-step"><div class="motion-number">0${i+1}</div><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}<div class="notice">${I('help')}This is an interactive demo. Email, OTP, passwords, shared records, and accounting sync need production services before real voting.</div>`,btn('Explore the voter flow','voter-preview','arrow','primary'))}
function demoInfo(){modal('About this demo workspace',`<p>Explore the full workflow with sample owners and ballots. Changes last while this tab remains open; reloading resets the demo.</p><div class="guide-step"><div class="square-icon">${I('check')}</div><div><h3>Ready to explore</h3><p>Excel/CSV import, MA verification, invitation previews, registration and OTP walkthrough, sequential ballots, results, and downloadable audit records.</p></div></div><div class="guide-step"><div class="square-icon">${I('settings')}</div><div><h3>Needed for a live AGM</h3><p>A protected shared database, managing-agent roles, secure password and OTP services, email delivery, accounting integration, and approved voting rules.</p></div></div><p>Use sample data only. Demo account forms do not store passwords or send emails.</p>`,btn('Got it','close-modal','check','primary'))}
function download(name,contents,type='text/csv;charset=utf-8'){let url=URL.createObjectURL(new Blob([contents],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n')}
function exportResults(){download('quorum-meeting-results.csv',csv([['Meeting',state.meeting],['Status',state.status==='closed'?'Final':'Provisional'],['Voting rule','One owner, one vote; abstentions excluded from approval percentage'],['Quorum required',state.quorum+'%'],['Participation',pct(stats().voted,stats().eligible)+'%'],[],['Motion','Type','For','Against','Abstained','Total','Approval %','Threshold %','Outcome'],...state.motions.map(m=>{let t=tally(m.id);return [m.title,m.type,t.For,t.Against,t.Abstained,t.For+t.Against+t.Abstained,pct(t.For,t.For+t.Against),m.threshold,passes(m)?'Approved':'Not approved']})]));log('RESULTS_EXPORTED','Managing agent','Meeting results exported as CSV.');toast('Meeting results downloaded.');render()}
function exportVotes(){download('quorum-owner-votes.csv',csv([['Owner ID','Owner','Unit','Motion ID','Motion','Choice','Submitted UTC','Receipt'],...state.ballots.flatMap(b=>b.choices.map(c=>{let o=state.owners.find(o=>o.id===b.ownerId),m=state.motions.find(m=>m.id===c.motionId);return [o?.id,o?.name,o?.unit,m?.id,m?.title,c.choice,b.time,b.receipt]}))]));log('OWNER_VOTES_EXPORTED','Managing agent','Owner-linked ballots exported as CSV.');toast('Owner vote report downloaded.');render()}
async function downloadAudit(){log('AUDIT_EXPORTED','Managing agent',`${state.status==='closed'?'Final':'Provisional'} audit package generated.`);let data={format:'quorum-audit-v1',mode:'DEMONSTRATION — not a production election record',generatedAt:new Date().toISOString(),status:state.status==='closed'?'FINAL':'PROVISIONAL',meeting:{name:state.meeting,community:state.hoa,date:state.date,status:state.status,closedAt:state.closedAt||null,rules:{quorum:state.quorum,weighting:'One vote per eligible owner',abstentions:'Excluded from approval denominator',ordinary:'More than 50%',special:'75% or more'}},owners:state.owners,motions:state.motions,ballots:state.ballots,outcomes:state.motions.map(m=>({motionId:m.id,...tally(m.id),approved:passes(m)})),events:allAudit()};let payload=JSON.stringify(data,null,2);if(crypto.subtle){let hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(payload));data={...data,payloadSha256:Array.from(new Uint8Array(hash)).map(x=>x.toString(16).padStart(2,'0')).join(''),checksumNote:'Checksum of JSON.stringify(data, null, 2) before payloadSha256 and checksumNote fields. This detects changes; it is not a digital signature.'}}download(`quorum-${state.status==='closed'?'final':'provisional'}-audit.json`,JSON.stringify(data,null,2),'application/json');toast('Audit file downloaded for verification.');render()}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('The CSV contains an unclosed quoted value.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);let headers=(rows.shift()||[]).map(x=>x.trim().replace(/^\uFEFF/,''));return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])))}
async function importFile(file){let preview=document.getElementById('import-preview'),confirm=document.getElementById('import-confirm');pendingImport=[];confirm.disabled=true;try{if(!file)return;if(file.size>2*1024*1024)throw Error('Choose a file smaller than 2 MB.');let rows;if(/\.csv$/i.test(file.name)){rows=parseCSV(await file.text())}else if(/\.xlsx?$/i.test(file.name)){if(!window.XLSX)throw Error('Excel reader is unavailable. Please export the spreadsheet as CSV.');let workbook=XLSX.read(await file.arrayBuffer(),{type:'array'});rows=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{defval:''})}else throw Error('Choose an Excel (.xlsx, .xls) or CSV file.');if(!rows.length)throw Error('The file has no owner rows.');if(rows.length>2000)throw Error('Import up to 2,000 owners at a time.');let normal=rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k.toLowerCase().trim().replace(/[ -]/g,'_'),v])));let required=['owner_name','email','unit','levy_balance'];for(let k of required)if(!(k in normal[0]))throw Error('Missing required column: '+k);let seen=new Set();pendingImport=normal.map((r,i)=>{let unit=String(r.unit).trim(),email=String(r.email).trim().toLowerCase(),name=String(r.owner_name).trim(),raw=String(r.levy_balance).trim().replace(/[R,\s]/g,''),balance=Number(raw);if(!name||!unit||!raw||!Number.isFinite(balance)||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error(`Row ${i+2}: provide a name, unit, valid email, and numeric levy balance.`);unit=/^\d+$/.test(unit)?unit.padStart(3,'0'):unit;if(seen.has(unit))throw Error(`Duplicate unit ${unit}. One owner record per unit is supported in this demo.`);seen.add(unit);let existing=state.owners.find(o=>o.unit===unit);if(existing&&state.ballots.some(b=>b.ownerId===existing.id)&&(existing.email!==email||existing.name!==name))throw Error(`Unit ${unit} already has a submitted ballot. Its owner or email cannot change.`);return {name,email,unit,balance}});let paid=pendingImport.filter(o=>o.balance<=0).length;preview.innerHTML=`<div class="import-summary"><strong>${pendingImport.length} valid records ready</strong><br>${paid} paid-up accounts · ${pendingImport.length-paid} outstanding balances<br>New and changed owners will require MA verification.</div>`;confirm.disabled=state.status==='closed';if(state.status==='closed')preview.innerHTML+='<div class="error">The meeting is closed. Owner imports are locked.</div>'}catch(e){pendingImport=[];preview.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
function commitImport(){if(!pendingImport.length||state.status==='closed')return;let added=0,updated=0;for(let r of pendingImport){let old=state.owners.find(o=>o.unit===r.unit);if(old){let changed=old.name!==r.name||old.email!==r.email||old.balance!==r.balance;let identityChanged=old.name!==r.name||old.email!==r.email;Object.assign(old,r);if(changed)old.approved=false;if(identityChanged){old.registered=false;old.invited=false;old.meetingInvited=false}updated++}else{state.owners.push({...r,id:Math.max(0,...state.owners.map(o=>o.id))+1,approved:false,registered:false,invited:false,meetingInvited:false});added++}}log('OWNERS_IMPORTED','Managing agent',`${added} owners added and ${updated} existing records updated. Source: accounting file import.`);closeModal();page='Owners & voters';ownerFilter='all';ownerSearch='';ownerPage=1;render();toast(`Import complete. ${added} added, ${updated} updated. Review eligibility next.`)}
function renderVoter(){let o=state.owners.find(o=>o.id===voter.ownerId)||state.owners[0];let content='';if(voter.stage==='welcome'){content=`<div class="voter-label">Owner portal · preview</div><h1>Your community.<br>Your voice.</h1><p class="subtitle">Take part in ${esc(state.meeting)} with a clear, guided voting experience.</p><div class="voter-card"><h2>Open your invitation</h2><p class="subtitle">Choose a sample owner to preview their personal email link.</p><div class="field" style="margin-top:22px"><label for="preview-owner">Sample owner</label><select id="preview-owner">${state.owners.map(x=>`<option value="${x.id}" ${x.id===o.id?'selected':''}>Unit ${esc(x.unit)} · ${esc(x.name)}${!eligible(x)?' · Not eligible':state.ballots.some(b=>b.ownerId===x.id)?' · Already voted':!x.registered?' · Not registered':''}</option>`).join('')}</select></div><div class="email-preview"><strong>${o.registered?'Your meeting is ready':'You’re invited to register'}</strong>Hello ${esc(o.name.split(' ')[0])},<br>${o.registered?'Sign in to access your ballot for':'Please register to vote at'} ${esc(state.meeting)}.</div>${btn(o.registered?'Open voting app':'Open registration invitation','voter-open','arrow','primary')}<p class="form-note">Interactive demonstration. No emails are sent and no real credentials should be entered.</p></div>`}else if(voter.stage==='register'){content=`<div class="voter-label">You’ve been invited</div><h1>Welcome, ${esc(o.name.split(' ')[0])}.</h1><p class="subtitle">Create your account to take part in your community’s decisions.</p><div class="voter-card"><h2>Register to vote</h2><p class="subtitle">${esc(state.hoa)} · Unit ${esc(o.unit)}</p><form id="register-form" style="margin-top:25px"><div class="field"><label>Email address</label><input value="${esc(o.email)}" disabled><small>Your invitation is linked to this owner record.</small></div><div class="field"><label for="register-username">Username</label><input id="register-username" name="username" required minlength="3" maxlength="40" placeholder="Choose a demo username" autocomplete="off"></div><div class="field"><label for="register-password">Password</label><input id="register-password" name="password" type="password" required minlength="8" placeholder="At least 8 characters · demo only" autocomplete="new-password"></div><div class="field"><label for="register-confirm">Confirm password</label><input id="register-confirm" name="confirm" type="password" required minlength="8" autocomplete="new-password"></div><div id="form-error"></div><label class="checkbox-row"><input name="consent" type="checkbox" required><span>I confirm that I am the invited owner and understand that votes are recorded against my owner record.</span></label>${btn('Create demo account','register-submit','arrow','primary','type="submit"')}<p class="form-note">Preview only. Passwords are not saved or used for authentication.</p></form></div>`}else if(voter.stage==='registered'){content=`<div class="voter-label">Registration complete</div><h1>You’re on the register.</h1><p class="subtitle">Your account is linked to Unit ${esc(o.unit)}.</p><div class="voter-card"><div class="receipt-icon">${I('check')}</div><h2 style="text-align:center">Registration received</h2><p class="subtitle" style="text-align:center">The managing agent will check your eligibility and send your meeting access invitation when voting opens.</p><div class="notice">${I('shield')}${eligible(o)?'Your owner record is verified and your levies are paid up.':'Your eligibility still needs managing-agent review.'}</div><div style="text-align:center;margin-top:24px">${btn('Preview MA meeting invitation','simulate-ma-invite','mail','primary')}</div><p class="form-note">Demo step: this simulates the managing agent preparing a meeting invitation. A live app sends the personal link by email.</p></div>`}else if(voter.stage==='login'){content=`<div class="voter-label">${esc(state.meeting)}</div><h1>Welcome back.</h1><p class="subtitle">Sign in to securely access your meeting ballot.</p><div class="voter-card"><h2>Sign in to vote</h2><p class="subtitle">${esc(o.name)} · Unit ${esc(o.unit)}</p><form id="login-form" style="margin-top:24px"><div class="field"><label for="login-username">Username</label><input id="login-username" name="username" required value="${esc(voter.username||'')}" placeholder="Enter a demo username" autocomplete="off"></div><div class="field"><label for="login-password">Password</label><input id="login-password" name="password" type="password" required minlength="8" placeholder="Any demo password, 8+ characters" autocomplete="off"></div><div id="form-error"></div>${btn('Continue to verification','login-submit','arrow','primary','type="submit"')}<p class="form-note">Demonstration sign-in accepts sample credentials. Never enter a real password here.</p></form></div>`}else if(voter.stage==='otp'){content=`<div class="voter-label">One more step</div><h1>Verify it’s you.</h1><p class="subtitle">A one-time code protects access to your ballot.</p><div class="voter-card"><div class="square-icon" style="margin-bottom:20px">${I('mail')}</div><h2>Check your email</h2><p class="subtitle">In a live meeting, the code is sent to ${esc(o.email)}.</p><div class="email-preview"><strong>Demo email preview</strong>Your verification code is <b style="font-size:20px;letter-spacing:4px">${voter.otp}</b><br>Valid for 5 minutes. No email has been sent.</div><form id="otp-form"><div class="field"><label for="otp-input">6-digit verification code</label><input id="otp-input" name="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required autocomplete="one-time-code" style="font-size:22px;letter-spacing:7px"></div><div id="form-error"></div>${btn('Verify & open ballot','otp-submit','shield','primary','type="submit"')}</form><div style="margin-top:20px"><button class="text-button" data-action="resend-otp">Generate a new demo code ${I('arrow')}</button></div></div>`}else if(voter.stage==='ballot'){let m=state.motions[voter.index];content=`<div class="voter-label">${esc(state.meeting)}</div><div style="display:flex;align-items:center;justify-content:space-between"><h1>Make your voice count.</h1>${badge('Voting open','live')}</div><p class="subtitle">${esc(o.name)} · Unit ${esc(o.unit)} · Verified owner</p><div class="stepper">${state.motions.map((x,i)=>`<i class="${i<=voter.index?'on':''}"></i>`).join('')}</div><div class="voter-card" style="margin-top:0"><div style="display:flex;justify-content:space-between;margin-bottom:20px"><span class="voter-label" style="margin:0">Motion ${voter.index+1} of ${state.motions.length}</span>${badge(m.type+' resolution','neutral')}</div><h2 style="font-size:22px;line-height:1.5">${esc(m.title)}</h2><p class="ballot-description">${esc(m.description)}</p><p style="font-size:12px;font-weight:600;margin-bottom:14px">How would you like to vote?</p>${['For','Against','Abstained'].map(c=>`<label class="vote-option ${voter.choices[m.id]===c?'selected':''}"><input type="radio" name="vote-choice" value="${c}" ${voter.choices[m.id]===c?'checked':''}><span>${c}</span>${voter.choices[m.id]===c?I('check'):''}</label>`).join('')}<div class="ballot-nav"><button class="text-button" data-action="ballot-back" ${voter.index===0?'disabled':''}>← Previous</button>${btn(voter.index===state.motions.length-1?'Review ballot':'Next motion','ballot-next','arrow','primary',!voter.choices[m.id]?'disabled':'')}</div><p class="form-note">Select one option to continue. Your complete ballot is registered only after you review and submit it.</p></div>`}else if(voter.stage==='review'){content=`<div class="voter-label">One final check</div><h1>Review your ballot.</h1><p class="subtitle">Check your choices before registering your votes.</p><div class="voter-card"><h2>${esc(state.meeting)}</h2><div class="receipt-list">${state.motions.map((m,i)=>`<div><span style="line-height:1.7">${i+1}. ${esc(m.title)}</span><div style="display:flex;align-items:start;gap:14px">${badge(voter.choices[m.id],'eligible')}<button class="text-button" data-edit-motion="${i}">Edit</button></div></div>`).join('')}</div><div class="notice">${I('lock')}Your ballot is final after submission. It is recorded against your verified owner record.</div><div style="margin-top:24px;display:flex;justify-content:flex-end">${btn('Submit my ballot','submit-ballot','check','primary')}</div></div>`}else if(voter.stage==='receipt'){let b=state.ballots.find(b=>b.ownerId===o.id);content=`<div class="voter-card receipt"><div class="receipt-icon">${I('check')}</div><div class="voter-label">Every voice. Accounted for.</div><h1>Your votes have<br>been registered.</h1><p>Thank you, ${esc(o.name.split(' ')[0])}. Your ballot for<br>${esc(state.meeting)} has been recorded.</p><div class="email-preview"><strong style="margin-bottom:4px">Ballot reference</strong><span style="font-family:monospace;font-size:17px;letter-spacing:2px">${esc(b?.receipt||'')}</span><br>${b?dateTime(b.time):''} UTC · Unit ${esc(o.unit)}</div><div class="receipt-list">${b?.choices.map(c=>`<div><span style="line-height:1.7">${esc(state.motions.find(m=>m.id===c.motionId)?.title)}</span>${badge(c.choice,'eligible')}</div>`).join('')||''}</div>${btn('Download my receipt','download-receipt','download')}<p class="form-note">You may now close the app. Your ballot cannot be submitted again.</p></div>`}else{content=`<div class="voter-card receipt"><div class="receipt-icon">${I('lock')}</div><h1>${esc(voter.blockTitle||'Voting unavailable')}</h1><p>${esc(voter.blockReason||'Please contact your managing agent.')}</p><div style="margin-top:24px">${btn('Back to owner preview','voter-restart','arrow','primary')}</div></div>`}document.getElementById('app').innerHTML=`<div class="voter-shell"><header class="voter-top"><div class="brand"><span class="brandmark"></span>quorum<span style="color:#8ca36c">.</span></div><div class="row-actions"><span class="demo-tag">OWNER PREVIEW</span>${btn('Back to workspace','admin-return','logout')}</div></header><main class="voter-main">${content}<p class="form-note" style="text-align:center;margin-top:28px">${I('shield')} ${esc(state.hoa)} · A guided owner voting experience</p></main></div>`}
function block(title,reason){voter.stage='blocked';voter.blockTitle=title;voter.blockReason=reason;renderVoter()}
function checkVoter(){let o=state.owners.find(o=>o.id===voter.ownerId);if(state.status!=='live'){block('Voting is closed','This meeting is no longer accepting votes. Please contact the managing agent.');return false}if(!o||!o.registered||!o.meetingInvited){block('Meeting access pending','Your registration and meeting invitation must be verified by the managing agent before you can vote.');return false}if(!eligible(o)){block('Eligibility review needed','The managing agent needs to verify your owner entitlement and paid-up levy balance. Please contact them for assistance.');return false}if(state.ballots.some(b=>b.ownerId===o.id)){voter.stage='receipt';renderVoter();return false}return true}
function newOtp(){voter.otp=String(100000+crypto.getRandomValues(new Uint32Array(1))[0]%900000);voter.otpExpires=Date.now()+300000;voter.attempts=0;log('OTP_GENERATED_DEMO',state.owners.find(o=>o.id===voter.ownerId).name,'Demo OTP generated; no email delivered.');voter.stage='otp';renderVoter()}
function formError(text){document.getElementById('form-error').innerHTML=`<div class="error" role="alert">${esc(text)}</div>`}
const actions={
'menu':()=>document.getElementById('sidebar').classList.toggle('open'),
'go-meetings':()=>{page='Meetings';render()},'go-results':()=>{page='Results & reports';render()},'go-owners':()=>{page='Owners & voters';render()},'go-audit':()=>{page='Audit trail';render()},
'close-modal':closeModal,'guide':guide,'demo-info':demoInfo,'notifications':()=>modal('Meeting notifications',`<div class="guide-step"><div class="square-icon">${I('vote')}</div><div><h3>${stats().voted} complete ballots received</h3><p>${stats().eligible-stats().voted} eligible owners have not yet submitted a ballot.</p></div></div><div class="guide-step"><div class="square-icon">${I('shield')}</div><div><h3>${stats().total-stats().eligible} owner records need attention</h3><p>Review outstanding levies and owner entitlement in the register.</p></div></div>`,btn('Review owners','go-owners','arrow','primary')),
'invite':()=>openInvite(false),'meeting-invites':()=>openInvite(true),
'confirm-invites':()=>{let n=0;state.owners.filter(eligible).forEach(o=>{o.invited=true;n++});log('INVITATIONS_PREPARED','Managing agent',`${n} registration invitations prepared in demo mode. No emails delivered.`);closeModal();render();toast(`${n} demo invitations prepared. No emails sent.`)},
'confirm-meeting-invites':()=>{if(state.status!=='live'){toast('The meeting is closed.');return}let n=0;state.owners.filter(o=>eligible(o)&&o.registered).forEach(o=>{o.meetingInvited=true;n++});log('MEETING_INVITES_PREPARED','Managing agent',`${n} meeting invitations prepared in demo mode. No emails delivered.`);closeModal();render();toast(`${n} demo meeting invitations prepared.`)},
'import':openImport,'confirm-import':commitImport,
 'template':()=>download('quorum-owner-import-template.csv',csv([['owner_name','email','unit','levy_balance'],['Alex Morgan','alex.morgan@example.com','149',0],['Jordan Lee','jordan.lee@example.com','150',1250]])),
'owners-prev':()=>{ownerPage=Math.max(1,ownerPage-1);document.getElementById('owners-table').innerHTML=ownersTable()},'owners-next':()=>{ownerPage++;document.getElementById('owners-table').innerHTML=ownersTable()},
'export-owners':()=>{download('quorum-owner-register.csv',csv([['Owner ID','Owner','Email','Unit','Levy balance','MA verified','Eligible','Registered','Invited'],...state.owners.map(o=>[o.id,o.name,o.email,o.unit,o.balance,o.approved,eligible(o),o.registered,o.invited])]));log('REGISTER_EXPORTED','Managing agent','Owner register exported.');toast('Owner register downloaded.');render()},
'export-results':exportResults,'export-votes':exportVotes,'download-audit':downloadAudit,'export-audit-csv':()=>{log('AUDIT_EXPORTED','Managing agent','Audit events exported as CSV.');download('quorum-audit-events.csv',csv([['Event ID','Timestamp UTC','Action','Actor','Details'],...allAudit().map(e=>[e.id,e.time,e.action,e.actor,e.details])]));render();toast('Audit events downloaded.')},
'close-meeting':()=>modal('Close the meeting?',`<p>All voting will end immediately. Existing ballots will be preserved, and owners will no longer be able to submit new ballots.</p><div class="import-summary"><strong>${stats().voted} complete ballots · ${state.motions.length} motions</strong><br>${stats().eligible-stats().voted} eligible owners have not voted.</div><p style="margin-top:18px">After closing, the final audit file is generated and downloaded for verification.</p>`,btn('Keep meeting open','close-modal')+btn('Close & generate audit','confirm-close','lock','danger')),
'confirm-close':()=>{if(state.status==='closed')return;state.status='closed';state.closedAt=new Date().toISOString();log('MEETING_CLOSED','Managing agent',`Meeting closed with ${stats().voted} complete ballots. Voting and eligibility changes locked.`);closeModal();downloadAudit();render()},
'edit-meeting':()=>{page='Settings';render()},
'add-motion':()=>{if(state.ballots.length){toast('The agenda is locked once voting begins.');return}modal('Add a meeting motion',`<form id="motion-form"><div class="field"><label for="motion-title">Motion title</label><input id="motion-title" name="title" required maxlength="150"></div><div class="field"><label for="motion-description">Full resolution</label><textarea id="motion-description" name="description" required></textarea></div><div class="field"><label for="motion-type">Resolution type</label><select name="type" id="motion-type"><option>Ordinary</option><option>Special</option></select></div>${btn('Add motion','motion-submit','plus','primary','type="submit"')}</form>`)},
'voter-preview':()=>{closeModal();view='voter';voter={stage:'welcome',ownerId:113,index:0,choices:{},verified:false};render();window.scrollTo(0,0)},
'admin-return':()=>{view='admin';render();window.scrollTo(0,0)},'voter-restart':()=>{voter.stage='welcome';renderVoter()},
'voter-open':()=>{let o=state.owners.find(o=>o.id===voter.ownerId);if(!o.invited){block('An invitation is needed','Please ask the managing agent to send your personal registration invitation.');return}if(state.ballots.some(b=>b.ownerId===o.id)){voter.stage='login'}else voter.stage=o.registered?'login':'register';log('INVITATION_OPENED',o.name,'Demo personal invitation opened.');renderVoter()},
'simulate-ma-invite':()=>{let o=state.owners.find(o=>o.id===voter.ownerId);if(!eligible(o)){block('Eligibility review needed','Your managing agent must verify your paid-up levy status and owner entitlement before sending a meeting invitation.');return}if(state.status!=='live'){block('Voting is closed','The meeting is no longer open for voting.');return}o.meetingInvited=true;log('MEETING_INVITE_PREPARED_DEMO','Managing agent',`Demo meeting invitation prepared for ${o.name}.`);voter.stage='login';renderVoter()},
'resend-otp':()=>{if(checkVoter())newOtp()},
'ballot-next':()=>{if(!checkVoter()||!voter.verified)return;let m=state.motions[voter.index];if(!voter.choices[m.id])return;if(voter.index<state.motions.length-1)voter.index++;else voter.stage='review';renderVoter();window.scrollTo(0,0)},
'ballot-back':()=>{voter.index=Math.max(0,voter.index-1);renderVoter()},
'submit-ballot':()=>{if(!voter.verified||!checkVoter())return;if(state.motions.some(m=>!['For','Against','Abstained'].includes(voter.choices[m.id]))){toast('Choose an option for every motion.');return}let receipt='QRM-2026-'+String(state.ballots.length+1).padStart(4,'0');state.ballots.push({ownerId:voter.ownerId,time:new Date().toISOString(),choices:state.motions.map(m=>({motionId:m.id,choice:voter.choices[m.id]})),receipt});voter.stage='receipt';renderVoter();window.scrollTo(0,0)},
'download-receipt':()=>{let b=state.ballots.find(b=>b.ownerId===voter.ownerId),o=state.owners.find(o=>o.id===voter.ownerId);if(b)download('quorum-ballot-receipt.txt',`QUORUM · DEMO BALLOT RECEIPT\n\n${state.meeting}\n${state.hoa}\nOwner: ${o.name}\nUnit: ${o.unit}\nReference: ${b.receipt}\nRegistered: ${b.time}\n\n${b.choices.map(c=>state.motions.find(m=>m.id===c.motionId)?.title+': '+c.choice).join('\n')}\n\nThis is a demonstration record.`, 'text/plain')}
};
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]'),p=e.target.closest('[data-page]'),f=e.target.closest('[data-motion-filter]'),o=e.target.closest('[data-owner]'),edit=e.target.closest('[data-edit-motion]');if(a){const name=a.dataset.action;if(['submit-settings','save-owner','register-submit','login-submit','otp-submit','motion-submit'].includes(name))return;if(name.startsWith('go-'))closeModal();actions[name]?.()}else if(p){page=p.dataset.page;render();window.scrollTo(0,0)}else if(f){motionFilter=f.dataset.motionFilter;render()}else if(o)openOwner(Number(o.dataset.owner));else if(edit){voter.index=Number(edit.dataset.editMotion);voter.stage='ballot';renderVoter()}if(e.target.classList.contains('modal-overlay'))closeModal()});
document.addEventListener('input',e=>{if(e.target.id==='owner-search'){ownerSearch=e.target.value;ownerPage=1;document.getElementById('owners-table').innerHTML=ownersTable()}if(e.target.id==='audit-search'){auditSearch=e.target.value;document.getElementById('audit-table').innerHTML=auditRows()}});
document.addEventListener('change',e=>{if(e.target.id==='owner-filter'){ownerFilter=e.target.value;ownerPage=1;document.getElementById('owners-table').innerHTML=ownersTable()}if(e.target.id==='owner-file')importFile(e.target.files[0]);if(e.target.id==='preview-owner'){voter.ownerId=Number(e.target.value);voter.verified=false;voter.choices={};renderVoter()}if(e.target.name==='vote-choice'){voter.choices[state.motions[voter.index].id]=e.target.value;renderVoter()}});
document.addEventListener('submit',e=>{e.preventDefault();let form=e.target,d=new FormData(form);if(form.id==='settings-form'){state.hoa=d.get('hoa').trim();state.meeting=d.get('meeting').trim();state.date=d.get('date');state.time=d.get('time');if(!state.ballots.length)state.quorum=Number(d.get('quorum'));log('SETTINGS_UPDATED','Managing agent','Community and meeting details updated.');render();toast('Meeting settings saved for this demo session.')}if(form.id==='owner-review-form'){if(state.status==='closed')return;let o=state.owners.find(o=>o.id===Number(form.dataset.id));o.balance=Number(d.get('balance'));o.approved=d.get('approved')==='on';log('ELIGIBILITY_UPDATED','Managing agent',`Unit ${o.unit}: balance R${o.balance.toFixed(2)}, MA verified ${o.approved?'yes':'no'}, eligible ${eligible(o)?'yes':'no'}.`);closeModal();render();toast('Owner verification updated.')}if(form.id==='register-form'){if(d.get('password')!==d.get('confirm')){formError('Passwords do not match. Please try again.');return}let o=state.owners.find(o=>o.id===voter.ownerId);if(!o.invited){block('Invitation required','Registration is available only through a managing-agent invitation.');return}voter.username=d.get('username').trim();o.registered=true;log('REGISTRATION_COMPLETED_DEMO',o.name,'Demo registration completed. No credentials stored.');voter.stage='registered';renderVoter()}if(form.id==='login-form'){if(!checkVoter())return;voter.username=d.get('username').trim();log('LOGIN_SIMULATED',state.owners.find(o=>o.id===voter.ownerId).name,'Demo sign-in step completed. No credentials authenticated.');newOtp()}if(form.id==='otp-form'){if(!checkVoter())return;if(Date.now()>voter.otpExpires){formError('This code has expired. Generate a new demo code.');return}voter.attempts++;if(voter.attempts>5){formError('Too many attempts. Generate a new demo code.');return}if(d.get('otp')!==voter.otp){log('OTP_REJECTED_DEMO',state.owners.find(o=>o.id===voter.ownerId).name,'Incorrect demo OTP entered.');formError('That code doesn’t match. Please check the demo email preview.');return}voter.verified=true;log('OTP_VERIFIED_DEMO',state.owners.find(o=>o.id===voter.ownerId).name,'Demo OTP matched and eligibility rechecked.');voter.stage='ballot';voter.index=0;renderVoter()}if(form.id==='motion-form'){if(state.ballots.length)return;state.motions.push({id:Math.max(0,...state.motions.map(m=>m.id))+1,title:d.get('title').trim(),description:d.get('description').trim(),type:d.get('type'),threshold:d.get('type')==='Special'?75:50});log('MOTION_CREATED','Managing agent','New motion added to the agenda.');closeModal();render();toast('Motion added.')}});
document.addEventListener('keydown',e=>{let root=document.getElementById('modal-root');if(!root.firstChild)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){let elements=[...root.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea,a[href]')],first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
state.owners[112].name='Alex Morgan';state.owners[112].email='alex.morgan@example.com';render();
